    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "पच्चीस piece तो एक ठो piece नहीं है।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "जी नहीं मैं IndiaMART से"
