      "speaker": "bot",
      "text": "मैं समझ सकती हूं पर मेरे पास उनके number नहीं हैं।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "हमारे पास और भी अच्छे sellers हैं जिनसे आप बात कर सकते हैं।"
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "मेहनत।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "जी बताइए।"
    },
    {
      "i": 20,
      "speaker": "caller",
      "text": "नहीं मैंने तो सामान लिया मुझे उससे बात करना था।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "मैं समझ सकती हूँ पर वो अभी unavailable हैं।"
    },
    {
      "i": 22,
      "speaker": "bot",
      "text": "आप उन्हीं seller को 10 minute बाद call कर लीजिएगा।"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "अपना समय देने के लिए धन्यवाद।"
